          </tr>
        }
      </tbody>
    </table>
    @if (editing(); as e) {
      <div class="glass"></div>
      <div class="popup" id="gwt-debug-manufacturer-editor">
        <div>
          <span>Name:</span>
          <input id="gwt-debug-manufacturer-input" type="text" [(ngModel)]="e.name" />
        </div>
        <div>
          <button id="gwt-debug-manufacturer-save" (click)="save(e)">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="editing.set(null)">Close</button>
        </div>
      </div>
    }
  `,
