export class ManufacturerComponent implements OnInit {
  private api = inject(Api);
  private messages = inject(Messages);
  manufacturers = signal<ManufacturerDto[]>([]);
  editing = signal<ManufacturerDto | null>(null);

  ngOnInit(): void { this.load(); }

  load(): void {
    this.api.getManufacturers().subscribe({
      next: list => this.manufacturers.set(list ?? []),
      error: () => this.messages.error('Error retrieving manufacturers'),
    });
  }

  create(): void { this.editing.set({ name: '', cars: [] }); }
  edit(m: ManufacturerDto): void { this.editing.set({ ...m }); }

  save(m: ManufacturerDto): void {
    const isNew = m.id == null;
    this.api.saveManufacturer(m).subscribe({
      next: saved => {
        this.editing.set(null);
        this.messages.success(`Manufacturer ${saved?.name ?? m.name} saved`);
        if (isNew) {
          this.manufacturers.update(l => [...l, saved]);
        } else {
          this.manufacturers.update(l => l.map(x => (x.id === saved.id ? saved : x)));
        }
      },
      error: () => this.messages.error('Error saving manufacturer'),
    });
  }

  remove(m: ManufacturerDto): void {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) { return; }
    this.api.deleteManufacturer(m.id as number).subscribe({
      next: () => {
        this.manufacturers.update(l => l.filter(x => x.id !== m.id));
        this.messages.success(`Manufacturer ${m.name} deleted`);
      },
      error: () => this.messages.error('Error deleting manufacturer'),
    });
  }
}
