import { Observable } from 'rxjs';

export interface ManufacturerDto { id?: number | null; name: string; cars?: CarDto[]; [k: string]: unknown; }
export interface CarDto { id?: number | null; model: string; manufacturer?: ManufacturerDto | null; [k: string]: unknown; }
export interface RatingDto { id?: number | null; rating: number | null; car: CarDto | null; [k: string]: unknown; }
export interface ManufacturerRatingDto { manufacturer: string; rating: number; }

const ROOT = '/api';

@Injectable({ providedIn: 'root' })
export class Api {
  private http = inject(HttpClient);
  getManufacturers(): Observable<ManufacturerDto[]> { return this.http.get<ManufacturerDto[]>(`${ROOT}/manufacturers`); }
  saveManufacturer(m: ManufacturerDto): Observable<ManufacturerDto> { return this.http.post<ManufacturerDto>(`${ROOT}/manufacturers`, m); }
  deleteManufacturer(id: number): Observable<unknown> { return this.http.delete(`${ROOT}/manufacturers/${id}`); }
  getAverageRatings(): Observable<ManufacturerRatingDto[]> { return this.http.get<ManufacturerRatingDto[]>(`${ROOT}/manufacturers/ratings`); }
  getRatings(): Observable<RatingDto[]> { return this.http.get<RatingDto[]>(`${ROOT}/ratings`); }
  saveRating(r: RatingDto): Observable<RatingDto> { return this.http.post<RatingDto>(`${ROOT}/ratings`, r); }
  deleteRating(id: number): Observable<unknown> { return this.http.delete(`${ROOT}/ratings/${id}`); }
  getCars(): Observable<CarDto[]> { return this.http.get<CarDto[]>(`${ROOT}/cars`); }
}

export function carLabel(car: CarDto | null | undefined): string {
  if (car && car.manufacturer) { return `${car.manufacturer.name}/${car.model}`; }
  return car ? car.model : '';
}
