  imports: [ManufacturerComponent, RatingComponent, ReportComponent],
  template: `
    <div class="header">
      <h1>Car Store</h1>
      <nav id="gwt-debug-menubar" class="menubar">
        <a href="#manufacturer" [class.active]="place() === 'manufacturer'">Manufacturers</a>
        <a href="#rating" [class.active]="place() === 'rating'">Ratings</a>
        <a href="#report" [class.active]="place() === 'report'">Reports</a>
      </nav>
    </div>
    <div class="messages">
      @for (m of messages.messages(); track m.id) {
        <div [id]="'gwt-debug-' + m.style + 'Message'" [class]="'message ' + m.style">
          <span>{{ m.text }}</span>
          <span class="close" (click)="messages.close(m.id)">×</span>
        </div>
      }
    </div>
    <div class="content">
      @switch (place()) {
        @case ('manufacturer') { <app-manufacturer /> }
        @case ('rating') { <app-rating /> }
        @case ('report') { <app-report /> }
      }
    </div>
  `,
})
export class AppComponent implements OnInit, OnDestroy {
  messages = inject(Messages);
  private zone = inject(NgZone);
  place = signal(DEFAULT_TOKEN);
  private listener = () => this.zone.run(() => this.sync());

  ngOnInit(): void {
    window.addEventListener('hashchange', this.listener);
    this.sync();
  }
  ngOnDestroy(): void { window.removeEventListener('hashchange', this.listener); }

  private sync(): void {
    const token = window.location.hash.replace(/^#!?\/?/, '').split(/[;?/]/)[0];
    if (TOKENS.includes(token)) {
      this.place.set(token);
    } else {
      this.place.set(DEFAULT_TOKEN);
      if (token !== DEFAULT_TOKEN) { history.replaceState(null, '', '#' + DEFAULT_TOKEN); }
    }
  }
}
EOF
