import { spawn } from 'node:child_process';
const chrome = spawn(process.env.CHROME_BIN, ['--headless','--no-sandbox','--disable-gpu','--remote-debugging-port=9333','about:blank']);
const sleep = ms => new Promise(r => setTimeout(r, ms));
await sleep(2000);
const targets = await (await fetch('http://127.0.0.1:9333/json')).json();
const ws = new WebSocket(targets.find(t => t.type === 'page').webSocketDebuggerUrl);
await new Promise(r => ws.onopen = r);
let id = 0; const pend = {};
ws.onmessage = e => { const m = JSON.parse(e.data); if (pend[m.id]) { pend[m.id](m); delete pend[m.id]; } };
const send = (method, params={}) => new Promise(r => { const i = ++id; pend[i] = r; ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async expr => (await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })).result.result.value;
const go = async h => { await send('Page.navigate', { url: 'http://localhost:8888/ng/' + h }); await sleep(2500); };
const rows = id => ev(`document.querySelectorAll('#${id} > tbody:first-of-type > tr').length`);
const cell = (id, col, r) => ev(`(()=>{const t=document.getElementById('${id}');const hs=[...t.querySelectorAll('thead th')].map(h=>h.innerText);const c=hs.indexOf('${col}');return t.querySelectorAll('tbody')[0].rows[${r}].cells[c].innerText})()`);
const typeIn = (sel, v) => ev(`(()=>{const i=document.querySelector('${sel}');i.value='${v}';i.dispatchEvent(new Event('input'));})()`);
const click = sel => ev(`document.querySelector('${sel}').click()`);
const log = (k, v) => console.log(k, JSON.stringify(v));
await send('Page.enable');
// Manufacturers
await go('#manufacturer');
let n = await rows('gwt-debug-manufacturers'); log('mfr rows', n);
await click('#gwt-debug-create-manufacturer'); await sleep(300);
log('editor visible', await ev(`!!document.getElementById('gwt-debug-manufacturer-editor')?.offsetParent || getComputedStyle(document.getElementById('gwt-debug-manufacturer-editor')).display`));
await typeIn('#gwt-debug-manufacturer-input', 'Ford'); await click('#gwt-debug-manufacturer-close'); await sleep(300);
log('rows after close', await rows('gwt-debug-manufacturers'));
await click('#gwt-debug-create-manufacturer'); await sleep(300);
await typeIn('#gwt-debug-manufacturer-input', 'Plymouth'); await click('#gwt-debug-manufacturer-save'); await sleep(1500);
log('success', await ev(`document.querySelector('#gwt-debug-successMessage span')?.innerText`));
log('rows after save', await rows('gwt-debug-manufacturers'));
log('last', await cell('gwt-debug-manufacturers', 'Name', (await rows('gwt-debug-manufacturers')) - 1));
await click('#gwt-debug-manufacturers tbody td:nth-last-child(2) button'); await sleep(300);
await typeIn('#gwt-debug-manufacturer-input', 'Ford'); await click('#gwt-debug-manufacturer-save'); await sleep(1500);
log('first after edit', await cell('gwt-debug-manufacturers', 'Name', 0));
await click('#gwt-debug-successMessage span:last-child'); await sleep(200);
log('msg closed', await ev(`!document.getElementById('gwt-debug-successMessage')`));
n = await rows('gwt-debug-manufacturers');
await ev(`window.confirm = () => true`); await click('#gwt-debug-manufacturers tbody td:last-child button'); await sleep(1500);
log('delete mfr', [n, await rows('gwt-debug-manufacturers')]);
// Ratings via menubar link
await ev(`[...document.querySelectorAll('#gwt-debug-menubar a')].find(a=>a.href.includes('rating')).click()`); await sleep(2000);
log('url', await ev('location.href'));
n = await rows('gwt-debug-ratings');
await click('#gwt-debug-ratingCreate'); await sleep(1500);
await typeIn('#gwt-debug-ratingInput', '10'); await click('#gwt-debug-ratingSave'); await sleep(1500);
log('rating create', [n, await rows('gwt-debug-ratings'), await ev(`document.querySelector('#gwt-debug-successMessage span')?.innerText`)]);
n = await rows('gwt-debug-ratings');
await ev(`window.confirm = () => true`); await click('#gwt-debug-ratings tbody td:last-child button'); await sleep(1500);
log('delete rating', [n, await rows('gwt-debug-ratings')]);
const avg = {}; const rn = await rows('gwt-debug-ratings');
for (let i = 0; i < rn; i++) { const car = await cell('gwt-debug-ratings','Car',i); const r = +await cell('gwt-debug-ratings','Rating',i); const m = car.slice(0, car.indexOf('/')); (avg[m] ??= []).push(r); }
await ev(`[...document.querySelectorAll('#gwt-debug-menubar a')].find(a=>a.href.includes('report')).click()`); await sleep(2000);
const pn = await rows('gwt-debug-reports'); let ok = pn > 0;
for (let i = 0; i < pn; i++) { const m = await cell('gwt-debug-reports','Manufacturer',i); const v = +await cell('gwt-debug-reports','Rating',i); const ref = avg[m].reduce((a,b)=>a+b,0)/avg[m].length; log('report', [m, v, ref]); ok &&= Math.abs(v-ref) < 0.001; }
log('reports ok', ok);
chrome.kill(); process.exit(0);
EOF
