package com.gwtplatform.carstore.cucumber.stepdefs;
import javax.inject.Inject;
import com.gwtplatform.carstore.cucumber.application.BasePage;
import com.gwtplatform.carstore.cucumber.application.widgets.HeaderWidgetPage;
import com.gwtplatform.carstore.cucumber.util.TestParameters;
import cucumber.api.java.en.Given;
import cucumber.runtime.java.guice.ScenarioScoped;
@ScenarioScoped
public class BasicStepDefs {
    private final BasePage basePage;
    private final HeaderWidgetPage headerWidgetPage;
    @Inject
    BasicStepDefs(BasePage basePage, HeaderWidgetPage headerWidgetPage) {
        this.basePage = basePage;
        this.headerWidgetPage = headerWidgetPage;
    }
    // Login/logout is out of scope for the Angular app (the REST API is not protected): just open the app.
    @Given("^I'm logged in$")
    public void imLoggedIn() {
        basePage.getUrl("about:blank");
        basePage.getUrl(TestParameters.BASE_URL);
    }
    @Given("^I navigate to the (\\S+) page$")
    public void navigateTo(String token) {
        headerWidgetPage.navigateTo(token);
        basePage.waitUntilPlaceIsLoaded(token);
    }
}
EOF
