package com.gwtplatform.carstore.cucumber;
import com.google.inject.*;
import cucumber.api.guice.CucumberModules;
import cucumber.runtime.java.guice.InjectorSource;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
public class CucumberModule extends AbstractModule implements InjectorSource {
    private static WebDriver driver;
    @Override protected void configure() {}
    @Provides WebDriver webDriver() {
        if (driver == null) {
            ChromeOptions o = new ChromeOptions();
            o.setBinary(System.getenv("CHROME_BIN"));
            o.addArguments("--headless", "--no-sandbox", "--disable-gpu", "--window-size=1280,1024");
            driver = new ChromeDriver(o);
            Runtime.getRuntime().addShutdownHook(new Thread(() -> driver.quit()));
        }
        return driver;
    }
    @Override public Injector getInjector() {
        return Guice.createInjector(Stage.PRODUCTION, CucumberModules.SCENARIO, this);
    }
}
EOF
